134	     */
135	    @ExceptionHandler(InvalidTelephoneException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
138	        logger.warn("Invalid telephone at {} {}: {}",
139	            request.getMethod(),
140	            request.getRequestURI(),
141	            e.getMessage());
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
144	        return ResponseEntity.status(status).body(detail);
145	    }
146	
147	    /**
148	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a
149	     * normalized telephone that is already used by another owner, returning a 409 Conflict status.
150	     *
151	     * @param e The {@link DuplicateTelephoneException} to be handled
152	     * @param request {@link HttpServletRequest} object referring to the current request.
153	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
154	     */
