156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
158	        logger.warn("Duplicate telephone at {} {}: {}",
159	            request.getMethod(),
160	            request.getRequestURI(),
161	            e.getMessage());
162	        HttpStatus status = HttpStatus.CONFLICT;
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
164	        return ResponseEntity.status(status).body(detail);
