167	    /**
168	     * Handles exception thrown by Bean Validation on controller methods parameters
169	     *
170	     * @param e The {@link MethodArgumentNotValidException} to be handled
171	     * @param request {@link HttpServletRequest} object referring to the current request.
172	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
173	     */
174	    @ExceptionHandler(MethodArgumentNotValidException.class)
175	    @ResponseBody
176	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
177	        HttpStatus status = HttpStatus.BAD_REQUEST;
178	        BindingErrorsResponse errors = new BindingErrorsResponse();
179	        BindingResult bindingResult = e.getBindingResult();
180	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
181	        if (bindingResult.hasErrors()) {
182	            errors.addAllErrors(bindingResult);
183	            List<String> errorFields = bindingResult.getFieldErrors().stream()
184	                .map(fieldError -> fieldError.getField())
185	                .distinct()
186	                .toList();
187	            detail.setProperty("errors", errorFields);
188	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
189	                .map(fieldError -> {
190	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
191	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
192	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
193	                        fieldError.getField(),
194	                        defaultMessage,
195	                        rejectedValue);
196	                    return new ValidationMessageDto(message)
197	                        .putAdditionalProperty("field", fieldError.getField())
198	                        .putAdditionalProperty("rejectedValue", rejectedValue)
199	                        .putAdditionalProperty("defaultMessage", defaultMessage);
200	                })
201	                .toList();
202	            logger.debug("Validation error at {} {}: {}",
203	                request.getMethod(),
204	                request.getRequestURI(),
205	                bindingResult.getFieldErrors());
206	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
207	            return ResponseEntity.status(status).body(detail);
208	        }
209	        return ResponseEntity.status(status).body(detail);
210	    }
